import sys

sys.setrecursionlimit(20000)

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes, target):
    if not nodes:
        return None, None

    root = Node(int(nodes[0]))
    queue = [root]
    idx = 1
    target_node = None

    while queue and idx < len(nodes):
        current = queue.pop(0)

        if nodes[idx] != 'null':
            val = int(nodes[idx])
            current.left = Node(val)
            queue.append(current.left)
            if val == target:
                target_node = current.left
        idx += 1

        if idx < len(nodes) and nodes[idx] != 'null':
            val = int(nodes[idx]) if nodes[idx] != 'null' else 0
            if nodes[idx] != 'null':
                current.right = Node(val)
                queue.append(current.right)
                if val == target:
                    target_node = current.right
        idx += 1

    return root, target_node

def find_mirror(root, target_val):
    if root is None:
        return None

    if root.data == target_val:
        return None

    if root.left and root.left.data == target_val:
        if root.right:
            return root.right.data
        return None
    if root.right and root.right.data == target_val:
        if root.left:
            return root.left.data
        return None

    left_result = find_mirror(root.left, target_val)
    if left_result is not None:
        return left_result

    right_result = find_mirror(root.right, target_val)
    if right_result is not None:
        return right_result

    return None

def main():
    try:
        line1 = sys.stdin.readline().strip()
        if not line1:
            return
        n = int(line1)

        line2 = sys.stdin.readline().strip()
        if not line2:
            return
        nodes_str = line2.split()

        line3 = sys.stdin.readline().strip()
        if not line3:
            return
        target = int(line3)

        root, _ = build_tree(nodes_str, target)
        result = find_mirror(root, target)

        if result is None:
            print("-1")
        else:
            print(result)
    except Exception:
        pass

if __name__ == "__main__":
    main()
